-- 2261 🏋️ Exercises from the book "jurgen-klopp-s-attacking-tactics-tactical-analysis-and-sessions-from-borussia-do" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'jurgen-klopp-s-attacking-tactics-tactical-analysis-and-sessions-from-borussia-do');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Winger drops, full back or No.10 exploits flank', 'combination', 'unopposed', 'in_possession', 61, 62, 'Session for Tactical Situation 1: Practice 1 - Creating Space On the Flank with Combination Play', 'Klopp (Borussia Dortmund)', 'Rehearse the movements that open and then use space on the flank, with players choosing between two options.', 'Two mirrored patterns run at once (left and right halves), each with a starter, full back, winger, No.10/centre forward pair, a wall player and an end player; two cone gates (option 1 and 2), a red trigger gate and a blue target box near the touchline.', 'The starter dribbles and picks one of two gates. Option 1: full back carries through the red gate, which triggers the winger to drop and the No.10 to run into the blue box for a long ball, then a 1-2 with the wall player and pass on. Option 2: the full back is pushed deep so the centre forward runs into the box instead.', 'Everyone rotates one position forward after each turn.', NULL, 'Read the picture and pick the right option at the right moment; check long-pass accuracy; time the weight of pass to each run.', 'about 10-12 players, two groups', 10, 12, NULL, NULL, NULL, NULL, false, false, true, NULL, 10),
  ('Build-up v 2 forwards, winger creates flank space', 'phase_of_play', 'overload', 'in_possession', 63, 64, 'Session for Tactical Situation 1: Practice 2 - Building Up Play Under Pressure from 2 Forwards, Creating and Exploiting Space on the Flank', 'Klopp (Borussia Dortmund)', 'Build up under pressure and find the full back so the winger can drop and the centre forward or No.10 can attack the space he leaves and cross.', '35 x 45 yard area cut into a low zone (a 25 x 15 yard yellow box, split into two halves), a middle zone for four forwards (split into strong and weak side) and a high zone with small target goals. Full backs stand in blue boxes on the touchlines, wingers in light-blue boxes, No.10 and centre forward on opposite sides.', 'Coach/GK plays into the low zone where it is 4 (+1) v 2. The yellows work the ball out to a full back; the strong-side winger then drops, the No.10 or centre forward (whoever is on that side) runs into the space, takes the full back''s pass and crosses at the near or far target goal. If the reds win it in the low zone they dribble over the end line.', 'Full backs may only leave their box by dribbling; the two reds may swap but must keep one in each horizontal half.', 'Require 3-4 passes before the ball can go to a full back.', 'Centre forward positions himself on the opposite side to the No.10; long pass must land inside the blue box; use the target goals to check cross quality.', '10 + GK/coach v 2', 13, 13, '35 x 45 yards', 41.1, 32.0, NULL, true, false, true, NULL, 20),
  ('Build-up v 2 forwards, full back high or low', 'phase_of_play', 'overload', 'in_possession', 65, 66, 'Session for Tactical Situation 1: Practice 3 - Building Up Play Under Pressure from 2 Forwards, Creating and Exploiting Space on the Flank (2)', 'Klopp (Borussia Dortmund)', 'Read whether the full back is high or deep to decide who exploits the space the winger creates.', 'As practice 2 but the full backs'' boxes are pushed higher, with a red channel across the field in front of the low zone; full backs may drop to act as outside support players.', 'The yellows aim to dribble through the red line. Then the strong-side winger drops: if the full back is high in his box he runs into the space; if he has dropped deep to help keep the ball, the No.10 or centre forward goes instead, and the move ends with a cross to target goals. Reds who win it dribble over the far end line.', 'Goalkeeper one touch; the forward pass must be played inside the red area; in the 4v2 the No.10 and centre forward keep to opposite sides.', 'Require 3-4 passes before dribbling through the red line.', NULL, '10 + GK v 2', 13, 13, NULL, NULL, NULL, NULL, true, true, true, NULL, 30),
  ('Build-up v 3 forwards, deep No.10 version', 'phase_of_play', 'overload', 'in_possession', 67, 68, 'Session for Tactical Situation 1: Practice 4 - Building Up Play Under Pressure from 3 Forwards, Creating and Exploiting Space on the Flank', 'Klopp (Borussia Dortmund)', 'Build out against three forwards with a deep No.10, so the full back or centre forward exploits the space the winger opens.', 'Same zones as the previous practice; the No.10 now starts deep in the red zone, and the low yellow zone is 4 (+2 +2) v 3.', 'The low-zone yellows either dribble into the red zone (full back then attacks the space) or pass from the high part of the zone to the full back (centre forward moves across to the strong side to attack it). The strong-side winger drops to create the space each time; finish with a cross. Reds who win it dribble over the end line.', 'Pass to the full back must come from the high part of the yellow zone; forward pass from midfielders or centre backs must be played inside the red zone.', 'Low-zone players must make 3-4 passes before passing to the full back or dribbling over the red line.', 'Centre forward places himself relative to the No.10; accurate long passes and crosses; synchronised movement.', '10 + GK v 3', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 40),
  ('Flank space and crossing, dynamic zonal practice', 'phase_of_play', 'opposed', 'in_possession', 69, 70, 'Session for Tactical Situation 1: Practice 5 - Building Up Play Under Pressure, Creating Space on the Flank and Crossing in a Dynamic Zonal Practice', 'Klopp (Borussia Dortmund)', 'Winger creates space and the right player, reading the situation, exploits it and crosses into the box.', 'Two thirds of a pitch with a goal and keeper, mannequins along the red line, four red defenders (two full backs in the blue touchline boxes) plus three red forwards in the low yellow zone against four yellows; yellow full backs and No.10 may leave their zones to support.', 'Low-zone yellows pass from the high part of the zone to a full back or dribble into the red zone; the strong-side winger then drops, drawing his marker, and the correct player runs into the space and crosses for team-mates timing runs into the box. Reds defend the goal and, if they win it in the low zone, dribble over the end line.', 'Red full backs must track their men but red centre backs may not enter the light-blue boxes; yellows must receive inside their box before dribbling out.', 'Require 3-4 passes before passing to the full back or dribbling through the red line.', NULL, '10 + coach v 7 + GK', 19, 19, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 50),
  ('Flank space and crossing, 11v11 zonal game', 'conditioned_game', 'opposed', 'in_possession', 71, 71, 'Session for Tactical Situation 1: Practice 6 - Building Up Play Under Pressure, Creating Space on the Flank and Crossing in an 11 v 11 Dynamic Zonal Game', 'Klopp (Borussia Dortmund)', 'Apply the winger-drops, partner-exploits pattern in a full game with counter-attacks for the defenders.', 'As practice 5 but with a full-size goal and keeper at the yellows'' end; 4 v 3 inside the low yellow zone, one red midfielder may enter it to help.', 'Keeper starts; yellows pass to a full back from the high part of the zone or dribble into the red zone, then the strong-side winger drops and the player on the strong side (No.10 in the example) attacks the space and crosses. Reds who win the ball anywhere try to score within 8-10 seconds.', 'Same restrictions and variation as practice 5.', NULL, NULL, '11 v 11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 60),
  ('Forward drops, No.10 or winger runs beyond', 'combination', 'unopposed', 'in_possession', 76, 76, 'Session for Tactical Situation 2: Practice 1 - The Forward Dropping Deep to Create Space in Behind with Combination Play', 'Klopp (Borussia Dortmund)', 'Rehearse the centre forward dropping to create space that the winger or No.10 then runs into and finishes.', 'Two blue zones (10 x 10 yards), two yellow zones (5 x 5 yards) and four mini goals; groups of A players start at the bottom, B players in the yellow zones, C players in the blue zones.', 'A passes through the left or right gate into a yellow zone, which makes B drop and set the ball back first time. A dribbles through the yellow cone gate, the C in the blue zone drops, and the other B makes a run into the blue zone to receive and shoot at a mini goal. Then repeat to the other side.', 'Players move on one position (A to B to C), except the dropping B who stays; C switches sides.', NULL, NULL, 'about 8-10 players', 8, 10, NULL, NULL, NULL, NULL, true, false, true, NULL, 70),
  ('Forward drops to free No.10, 4(+3)v3 build-up', 'phase_of_play', 'overload', 'in_possession', 77, 77, 'Session for Tactical Situation 2: Practice 2 - Building Up Play with the Forward Dropping Deep to Create Space in Behind for the No.10', 'Klopp (Borussia Dortmund)', 'Build up and use the centre forward''s drop to create space behind for the No.10 to run onto and score.', 'Large zone 30 x 25 yards split vertically in two, with outside players on the sides; two blue zones (10 x 10 yards) for the centre forward and two yellow zones (5 x 5 yards) for the No.10 up the field; two mini goals at each end.', 'Coach/GK feeds into the large zone for 4 (+3) v 3. Centre forward goes to the strong side, No.10 to the weak side. Once a yellow dribbles over the red line, the centre forward drops, the No.10 runs forward into the space and receives a long pass to score in a mini goal. Reds who win it attack the two mini goals at the other end.', 'The 3 outside players have one touch or must return the ball within 3 seconds; yellows need 3-4 passes before dribbling over the red line.', NULL, NULL, '9 + coach v 3', 13, 13, 'large zone 30 x 25 yards', 27.4, 22.9, NULL, true, false, true, NULL, 80),
  ('Forward drops to free winger, 4(+3)v3 build-up', 'phase_of_play', 'overload', 'in_possession', 78, 78, 'Session for Tactical Situation 2: Practice 3 - Building Up Play with the Forward Dropping Deep to Create Space in Behind for the Winger', 'Klopp (Borussia Dortmund)', 'Wingers learn to attack the space left when the centre forward drops deep.', 'As practice 2 but the yellow zones sit wide for the two wingers; the centre forward picks the strong side according to where the ball is in the large zone.', 'When a yellow dribbles over the red line, the centre forward drops and the strong-side winger cuts inside into the space, receives a long pass and shoots at a mini goal. Reds who win the ball attack the two mini goals at the other end.', 'Outside players one touch or return within 3 seconds; 3-4 passes before dribbling over the red line.', NULL, NULL, '9 + coach v 3', 13, 13, NULL, NULL, NULL, NULL, true, false, true, NULL, 90),
  ('Forward drops to create space, 10v7 zonal game', 'phase_of_play', 'opposed', 'in_possession', 79, 79, 'Session for Tactical Situation 2: Practice 4 - The Forward Dropping Deep to Create Space in Behind in a 10 v 7 Zonal Game', 'Klopp (Borussia Dortmund)', 'Create time for a forward pass, then use the centre forward''s drop so the right attacking midfielder exploits the space and shoots.', 'Two thirds of a pitch with a goal and keeper; low zone with 5 (+2) v 4; three yellow zones for the attacking midfielders (10, 11, 17), centre forward on the strong side, a light-blue zone in front of goal.', 'Coach/GK starts. The attacking midfielder in the ball''s section drops into the red zone as an extra player. When the man on the ball has time, the centre forward drops and the right player runs into the space to receive and shoot. The strong-side red defender tracks the centre forward; the other may follow the runner but not enter the strong-side light-blue zone. Reds who win it try to score within 8 seconds.', 'Same restrictions as previous practices.', NULL, NULL, '10 v 7 (+ GKs)', 19, 19, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 100),
  ('Up-and-down movement to receive and shoot', 'combination', 'unopposed', 'in_possession', 93, 93, 'Session for Tactical Situation 3: Practice 1 - Getting Free of Marking With an Up and Down Movement To Attack Forward Quickly', 'Klopp (Borussia Dortmund)', 'Train getting free of marking with a check up-and-back (or by dropping) and turning to finish quickly.', 'Two stations side by side, each with a blue zone (8 x 20 yards) holding player C, a cone gate in midfield, a mini goal and a bigger goal at the end; A and B start below.', 'Left: A passes to B and moves left or right, B sets it back; C runs up to touch a red cone then drops back. As A dribbles through the gate, he passes to C who receives half-turned and shoots into the mini goal or diagonally into the big goal. Right: C first moves to a purple cone, which tells A which way to go, then drops back as A comes through the gate. Rotate A to B to C to A; switch sides after 7-8 minutes.', 'C must receive and pass inside the blue zone using two touches (receive on the turn, then pass/shoot).', NULL, NULL, '2 groups of 3+', 6, 12, NULL, NULL, NULL, 15.0, true, false, true, NULL, 110),
  ('Up-and-down movement, 6(+1)v4 then pass behind', 'phase_of_play', 'overload', 'in_possession', 94, 95, 'Session for Tactical Situation 3: Practice 2 - Building Up, Getting Free of Marking With an Up and Down Movement and Passing in Behind the Defence', 'Klopp (Borussia Dortmund)', 'Combine getting free of marking with an up-and-down movement with passes in behind for attacking runs.', 'Large zone split in three sections with 6 (+1) v 4, coach/GK as the outside player; centre forward (9) and two wingers (11, 17) in blue zones ahead, mannequins as defenders and mini goals beyond.', 'Yellows try to dribble over the red end line. If it is through a side section, that winger touches the mannequin and drops back to receive; through the middle, the centre forward does it. He receives and turns at once while the other two run behind the mannequins to receive and score in the mini goals. Reds who win it dribble over the opposite end line.', 'Coach/GK one touch or return within 3 seconds; set a pass count (e.g. 3-4) before dribbling over the red line.', NULL, 'Read which movement and pass to choose; turn quickly with a good half-turn first touch; quick, accurate, well-weighted final pass; quick accurate shot; synchronised movements.', '9 + coach v 4 (+ mannequins)', 14, 14, NULL, NULL, NULL, NULL, true, false, true, NULL, 120),
  ('Dropping-back movement, 4(+3)v3 then pass behind', 'phase_of_play', 'overload', 'in_possession', 96, 96, 'Session for Tactical Situation 3: Practice 3 - Building Up, Getting Free of Marking With a Dropping Back Movement and Passing in Behind the Defence', 'Klopp (Borussia Dortmund)', 'Get free of marking by dropping deep and set up attacking combinations in behind.', '4 (+3) v 3 in the large zone with outside players 1, 29 and 26; cones mark three narrower lanes. Centre forward in a high central yellow zone, wingers in smaller side zones, No.10 in the central blue zone; mannequins and mini goals beyond.', 'When the ball is dribbled over the line, the player for that lane (winger for a purple side line, centre forward for the red middle line) drops into a blue zone, receives on the half-turn and passes in behind for one of his three team-mates to score. Reds who win it dribble over the far end line.', 'Outside players one touch or return within 3 seconds.', NULL, NULL, '9 v 3 (+ mannequins)', 12, 12, NULL, NULL, NULL, NULL, true, false, true, NULL, 130),
  ('Get free and pass behind, 6(+1)v4 dynamic game', 'phase_of_play', 'opposed', 'in_possession', 97, 98, 'Session for Tactical Situation 3: Practice 4 - Building Up, Getting Free of Marking and Passing in Behind the Defence in a Dynamic Game', 'Klopp (Borussia Dortmund)', 'Use up-and-down or dropping-deep movements to get free against active defenders, then combine in behind.', 'Two thirds of a pitch with goal and keeper; 6 (+1) v 4 in the white zone; four red defenders in yellow zones (2 yard gaps). Centre forward free in the two central yellow zones (7 x 7 yards), wingers in side zones (9 x 7 yards), No.10 in the central blue zone on the weak side. Reds counter to two mini goals.', 'Yellows dribble over the end line (red, purple or white). The matching player drops or checks up and back into a blue zone, receives half-turned and passes in behind for a team-mate to score past the keeper. White line: winger must use up-and-down; purple: winger may use either; red: centre forward can also use either. Reds who win it score in the mini goals within 8-10 seconds.', 'Coach/GK one touch or return in 3 seconds; defenders follow the first upward movement but let the player drop to receive free; they do not follow a dropping movement at all; defenders stay in their yellow zones; pass count (e.g. 3-4) before dribbling over the line.', NULL, NULL, '10 + coach v 6 + GK', 18, 18, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 140),
  ('Get free and pass behind, with red DMs', 'phase_of_play', 'opposed', 'in_possession', 99, 99, 'Session for Tactical Situation 3: Practice 5 - Building Up, Getting Free of Marking and Passing in Behind the Defence in a Dynamic Game (2)', 'Klopp (Borussia Dortmund)', 'Forwards recognise when the ball carrier can play forward and use the right movement to get free against midfield screening.', 'As practice 4 plus two red defensive midfielders positioned between the low zone and the forward zones; yellows'' keeper and goal at their end.', 'Low-zone yellows no longer have to dribble over the line and may pass forward from inside the zone, while the two red midfielders try to block or intercept. The forwards read when a forward pass is on and get free by dropping or checking up and back, then combine in behind to score. Reds who win it score within 8-10 seconds with no zone limits.', 'Same restrictions as practice 4.', NULL, NULL, '10 + GK v 8 + GK', 20, 20, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Complex combination to exploit 2nd-stage space', 'passing_unopposed', 'unopposed', 'in_possession', 109, 109, 'Attacking Tactical Situation 4 - Session: Practice 1', 'Klopp (Borussia Dortmund)', 'Creating and then exploiting space in the second stage of attack with a multi-pass combination.', '30x30-ish grid split in two halves, each with a start player, cone gates, small blue target zones and cones/mannequins; runs simultaneously on both sides.', 'Opener plays a 1-2 with a midfielder; as that happens the striker drops and the No.10 runs into the vacated zone. After the dribble through the cone gate the ball goes to the dropping striker, who sets it to the No.10 (or a supporting player), who enters the blue zone, dribbles on and passes to the next start. Left side mirrors it with winger dropping and striker running in.', NULL, NULL, 'Pass speed, weight and accuracy; synchronise timing of passes with movements.', 'about 11-12 players', 10, 14, NULL, NULL, NULL, NULL, false, false, true, NULL, 160),
  ('Complex combination in dynamic zonal practice', 'phase_of_play', 'overload', 'in_possession', 110, 111, 'Attacking Tactical Situation 4 - Session: Practice 2', 'Klopp (Borussia Dortmund)', 'Creating and exploiting space near the touchline using a complex combination.', 'Full pitch: dark blue low zone with a 3(+4)v2 (GK, two full backs and DM outside), wingers in light blue side zones, striker in a central zone and No.10 between zone sets, 3 mannequins; 2 mini goals for reds.', 'Yellows circulate in the low zone until a forward pass is on; the winger on that side drops to receive while the No.10 or striker runs into the space he left. The winger finds the DM or No.10, who slides the final pass into the runner, who crosses for teammates to score. Reds counter to the mini goals if they win it.', 'Outside players 1 touch or must return the ball into the zone within 3 seconds; optionally require 3-4 passes before the forward pass.', NULL, 'Read the situation on the strong side and know who to pass to and when.', '3(+4)v2 plus forwards and GK', 12, 16, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Central complex combination zonal variation', 'phase_of_play', 'overload', 'in_possession', 112, 113, 'Attacking Tactical Situation 4 - Session: Practice 3', 'Klopp (Borussia Dortmund)', 'Exploiting space created in the centre with a complex passing combination and a finish.', 'As previous practice but with only central zones outside the box: striker in one of two light blue zones, No.10 in red zones, wingers by white cones; 3(+4)v2 in the dark blue low zone; mini goals for reds.', 'When a forward pass is on, the striker drops into the red zone on the strong side and the No.10 makes a diagonal run into the space created. The striker plays to the winger or DM, who threads the final ball into the No.10 to dribble and finish past the GK.', 'Same as previous practice (1 touch / 3-second return for outside players, pass count before forward pass).', 'Variation of practice 2.', NULL, '3(+4)v2 plus forwards and GK', 12, 16, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 180),
  ('Exploiting flank space in zonal SSG', 'small_sided_game', 'opposed', 'in_possession', 114, 114, 'Attacking Tactical Situation 4 - Session: Practice 4', 'Klopp (Borussia Dortmund)', 'Creating and exploiting space centrally or near the sidelines against defenders who track droppers.', 'Full-pitch zones with 2 wide channels for the wingers; 4 red defenders in light blue zones marking direct opponents; 3(+3)v3 in the low zone; 2 mini goals for reds.', 'Yellows build in the low zone; on a forward pass the winger drops, his marker follows once the pass is played, and the space behind is exploited via a combination with the DM. Yellows try to score; reds win it and attack the mini goals.', 'Outside players 1 touch or return within 3 seconds; red defenders may not enter other light blue zones but can leave their own to defend e.g. a cross.', NULL, 'Read whether to create/exploit space in the centre or near the sidelines.', '3(+3)v3 plus forwards v 4 defenders + GK', 16, 20, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 190),
  ('Complex combination dynamic zonal 11v11', 'conditioned_game', 'opposed', 'in_possession', 115, 115, 'Attacking Tactical Situation 4 - Session: Practice 5', 'Klopp (Borussia Dortmund)', 'Applying complex combinations to create and exploit space in a full game situation.', 'Full pitch with zones; 3 red midfielders replace the mannequins; 6(+GK)v3 in the dark blue zone; second full-size goal for reds.', 'Yellows aim to pass through the 3 red midfielders; a forward (e.g. the 9) drops to create space and teammates exploit it with a combination. Reds counter and must score within 8-10 seconds.', 'Red defenders cannot enter other light blue zones; red midfielders stay in their areas unless a forward pass is played to a yellow forward; no zone limits once reds win it; optionally 3-4 passes before the forward pass.', NULL, NULL, '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 200),
  ('Carrying out from the back to overload', 'passing_unopposed', 'unopposed', 'in_possession', 121, 121, 'Attacking Tactical Situation 5 - Session: Practice 1', 'Klopp (Borussia Dortmund)', 'Creating superiority near the sideline with a centre back or DM carrying the ball forward.', '30x30 yard area with two mirrored circuits, cone gates and mannequins; start players at opposite ends.', 'Right: opener feeds a runner who dribbles through the gate; a forward drops but the mannequin blocks the vertical lane, so the carrier passes directly wide; the wide man then breaks to the sideline, receives behind a second mannequin, dribbles through and passes to the next start. Left: carrier dribbles in, a player drops and lays off first time to a forward runner who plays back into the carrier''s run; all rotate one position.', NULL, NULL, NULL, 'about 10-12 players', 10, 14, '30 x 30 yards', 27.4, 27.4, NULL, false, false, true, NULL, 210),
  ('3v2 flank overload exercise', 'one_v_one', 'overload', 'in_possession', 122, 122, 'Attacking Tactical Situation 5 - Session: Practice 2', 'Klopp (Borussia Dortmund)', 'Using a 3v2 on the flank to break past defenders.', 'Two 15x25 yard blue zones (split into two halves), one red defender in each half, a yellow in the high and low halves of each zone who must stay put; starts in the middle.', 'First pass is played into a forward-running yellow who enters the zone with the ball and with his two teammates uses the 3v2 to dribble through the red line or pass to a free teammate beyond it. The successful player returns to the start and others rotate.', 'Zone players cannot leave their sections.', NULL, 'Keep the ball moving quickly; accurate weighted passing; timing of passes and runs.', '3v2 each side', 10, 14, '15 x 25 yard zones', 22.9, 13.7, NULL, false, false, true, NULL, 220),
  ('Flank 3v2 overload in 8v8 SSG', 'small_sided_game', 'opposed', 'in_possession', 123, 124, 'Attacking Tactical Situation 5 - Session: Practice 3', 'Klopp (Borussia Dortmund)', 'Building from the back to create a 3v2 on the flank in a game.', '55x45 yard area, 8v7 (+GK); blue zones on each flank with a 2v2; 3 yellows v 2 reds in the defensive half; yellow striker v red centre back up top; 2 mini goals for reds.', 'Coach passes to one side; a deep yellow receives and carries into the blue zone to make 3v2, then dribbles through the red line or receives beyond it, and the attack is finished on goal. Offside applies; zone limits end once the ball leaves the blue zone.', 'The 4 reds in the defensive half may only enter it after a pass to a yellow there; zone defenders stay in the zone; reds must score in the mini goals within 10 seconds of winning it.', NULL, NULL, '8v7 (+GK)', 16, 16, '55 x 45 yards', 50.3, 41.1, NULL, true, true, true, NULL, 230),
  ('Flank 3v2 in 11v11 with side zones', 'conditioned_game', 'opposed', 'in_possession', 125, 125, 'Attacking Tactical Situation 5 - Session: Practice 4', 'Klopp (Borussia Dortmund)', 'Creating and using 3v2 superiority on the flank in an 11v11 game.', 'Two thirds of a full pitch, second full-size goal; blue side zones 15x25 yards; yellow GK starts.', 'Yellows build up to create a 3v2 in a blue zone, dribble through the red line or receive behind it, then cross or shoot. Reds defend and must finish a counter within 8-10 seconds.', 'Only the red full back and winger may defend in the side zones, and not beyond the red line.', NULL, NULL, '11v11', 22, 22, '2/3 of full pitch', NULL, NULL, NULL, true, true, true, NULL, 240),
  ('Forward drops to overload flank circuit', 'passing_unopposed', 'unopposed', 'in_possession', 133, 133, 'Attacking Tactical Situation 6 - Session: Practice 1', 'Klopp (Borussia Dortmund)', 'Combination play where a forward moves to receive and creates a numerical advantage on the flank.', '30x30 yard area, two mirrored circuits with cone gates, mannequins and small 5x7 yard blue zones.', 'Right: runner dribbles through the gate; a player shows in front of a mannequin, receives, turns in the blue zone and passes into the path of a teammate who has got free of his mannequin; he plays a 1-2 and passes to the far start. Left: a player drops in front of the mannequin and another opens up; the dropping player receives and plays first time without turning, then a 1-2 and back to the start; all rotate.', NULL, NULL, NULL, 'about 10-12 players', 10, 14, '30 x 30 yards', 27.4, 27.4, NULL, false, false, true, NULL, 250),
  ('No.10 moves to overload the flank', 'combination', 'unopposed', 'in_possession', 134, 135, 'Attacking Tactical Situation 6 - Session: Practice 2', 'Klopp (Borussia Dortmund)', 'Forward (No.10 or striker) moving to receive to overload the flank, then finishing.', '2/3 of a pitch; 15x35 yard blue zone split into 8 sections with mannequins; striker and wingers in high sections, No.10 in low sections; red full-back target zones; GK in goal; spare forwards waiting.', 'Two centre backs pass until one carries forward (trigger) or plays to a full back in a red zone. The No.10 receives and turns towards the overloaded side, then plays wide (option 1) or a killer pass (option 2); the receiver shoots or crosses.', 'Wingers stay in their zones; the striker can move in or out of the two high central zones.', 'Variation: the striker drops to create the overload while the No.10 stays on the weak side.', NULL, 'about 10-12 + GK', 10, 14, '2/3 of full pitch', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('Forward overload in dynamic zonal SSG', 'small_sided_game', 'overload', 'in_possession', 136, 137, 'Attacking Tactical Situation 6 - Session: Practice 3', 'Klopp (Borussia Dortmund)', 'Moving the ball forward and overloading the flank with a forward who drops to receive.', 'As previous practice with 4 red defenders in zones; 4(+3)v2(+1) in the low zone with GK/coach starting; 2 mini goals for reds.', 'Yellows look for the forward pass; the No.10 or striker moves to overload the flank, receives, turns and plays wide to the advancing full back or winger making a curved run, who crosses for runners to finish.', 'Red defenders stay in their zones until the ball is played wide beyond the red line; only one red DM may enter the first zone.', NULL, 'Quality and speed when turning; weight and accuracy of passes; synchronised movement.', '4(+3)v2(+1) plus forwards v 4 defenders + GK', 16, 20, '2/3 of full pitch', NULL, NULL, NULL, true, true, true, NULL, 270),
  ('Forward overload in 11v11 zonal game', 'conditioned_game', 'opposed', 'in_possession', 138, 138, 'Attacking Tactical Situation 6 - Session: Practice 4', 'Klopp (Borussia Dortmund)', 'Forward moving to receive to overload the flank within an 11v11.', 'Full-width first zone with 6(+GK)v5, extra white zone, second full-size goal.', 'Once yellows play forward, the No.10 or striker creates an overload and the attack is finished as in the previous practice. Reds counter and must score within 8-10 seconds.', 'Red defenders stay in zones until the ball goes wide past the red line; one red DM may enter the first zone; no zone limits after a successful forward pass or a turnover; optionally 3-4 passes first.', NULL, NULL, '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 280),
  ('Vertical then square pass combination', 'passing_unopposed', 'unopposed', 'in_possession', 144, 144, 'Attacking Tactical Situation 7 - Session: Practice 1', 'Klopp (Borussia Dortmund)', 'A vertical or diagonal pass followed by a square pass in tight space.', '30x30 yard area with mannequins, cone gates and 10x3 yard blue zones; dark blue end zones.', 'Starters dribble through gates, triggering players behind the mannequins to move into passing lanes. The ball goes through the wider lane, then is squared in the blue zone, then played forward into a runner in the dark blue zone, who passes back to the start on the other side; all rotate.', NULL, NULL, 'High accuracy and speed in tight space; pass weight synchronised with timed runs.', 'about 10-12 players', 10, 14, '30 x 30 yards', 27.4, 27.4, NULL, false, false, true, NULL, 290),
  ('Vertical + square pass 5-zone possession', 'positional_game', 'overload', 'in_possession', 145, 146, 'Attacking Tactical Situation 7 - Session: Practice 2', 'Klopp (Borussia Dortmund)', 'Playing through lines with a vertical/diagonal plus square pass combination.', '20x40 yard area split into 5 zones: end zones 20x17, a central 20x3 zone with two 20x2 zones either side; 3 yellows v 2 reds in an end zone, 2 yellows in zone 3, 3 reds in zone 2.', 'Yellows make at least 3 passes then play into zone 3, where the two carry out the vertical/diagonal + square combination and pass to teammates in the far end zone. Reds then shift up to defend and play continues the other way; reds keep possession if they win it.', 'Most switches in 2-4 minutes then swap roles; one red outside runs on; coach feeds a new ball into an end zone when out of play.', 'If it is too hard to reach zone 3, one of the 3 reds can move outside.', 'Intelligent off-ball movement; accuracy and speed of passing in tight space.', '3v2 + 2 in middle zone v 3', 10, 12, '20 x 40 yards', 36.6, 18.3, NULL, false, false, true, NULL, 300),
  ('Square pass combo and decision making', 'phase_of_play', 'overload', 'in_possession', 147, 147, 'Attacking Tactical Situation 7 - Session: Practice 3', 'Klopp (Borussia Dortmund)', 'Using the vertical/diagonal + square combination and choosing the right final pass.', '2/3 of a pitch; 4(+3)v2(+1) in a 30x20 yard low zone; 3 yellow midfielders in a 25x3 yard blue zone; striker outside; mannequins; GK; 2 mini goals.', 'GK starts; yellows with full backs and GK find a forward pass to the midfielders, who combine vertical/diagonal then square; the new man on the ball picks the final pass while others run to receive and score past the GK. Reds score in mini goals if they win it in the first zone.', 'Only one red DM may enter the first zone; outside yellows (GK, full backs) 1 touch while the zone keeps possession.', NULL, NULL, '4(+3)v2(+1) + midfielders and striker + GK', 14, 16, '2/3 of full pitch', NULL, NULL, NULL, true, true, true, NULL, 310),
  ('Square pass combinations in 4-zone 11v11', 'conditioned_game', 'opposed', 'in_possession', 148, 148, 'Attacking Tactical Situation 7 - Session: Practice 4', 'Klopp (Borussia Dortmund)', 'Vertical/diagonal + square combinations and finishing in an 11v11 game.', 'First zone 45x25 yards full width, blue midfield zone 25x3 yards, white zone with 4 defenders and the striker; second full-size goal; 6v4(+1) in the first zone.', 'GK starts; yellows find the 3 midfielders, who perform the combination; the new man on the ball looks for the final pass and teammates run to receive and score. Reds counter freely and must score within 8-10 seconds.', 'One red DM may enter the first zone; red midfielders/forwards may track back; red defenders can leave the white zone to press but not defend beyond the red line.', NULL, NULL, '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 320),
  ('Lay-off combination to finish', 'combination', 'unopposed', 'in_possession', 152, 152, 'Attacking Tactical Situation 8 - Session: Practice 1', 'Klopp (Borussia Dortmund)', 'An attacking combination using a lay-off in limited space.', '30x30 yard area, two mirrored sides with cone gates, mannequins, blue zones and a mini goal at each end.', 'Two starters dribble through gates while players on white cones move towards the blue zones and forwards check (up then drop) off mannequins. On the trigger the forward pass goes to the forward, who lays off into the blue zone; the receiver passes to one of two forwards running behind the mannequins, who finishes first time in the mini goal; all rotate.', NULL, NULL, NULL, 'about 10-12 players', 10, 14, '30 x 30 yards', 27.4, 27.4, NULL, true, false, true, NULL, 330),
  ('Lay-off through centre end-to-end game', 'positional_game', 'overload', 'in_possession', 153, 153, 'Attacking Tactical Situation 8 - Session: Practice 2', 'Klopp (Borussia Dortmund)', 'Passing through the centre using a lay-off combination.', '30x30 yard area split in halves; 3(+1 neutral)v3 in each half plus 2 neutrals in centre semicircles; coach with balls.', 'The team in possession plays into the advanced neutral, who lays off to the deeper neutral, who then passes to a teammate in the other half to switch. If defenders win it they attack with the same aim.', 'Team with most switches in 4-5 minutes wins.', NULL, 'Check away from markers before showing; accurate quick passing and dribbling in tight space.', '6(+4)v6', 16, 16, '30 x 30 yards', 27.4, 27.4, NULL, false, false, true, NULL, 340),
  ('Build under pressure via lay-off', 'phase_of_play', 'overload', 'in_possession', 154, 154, 'Attacking Tactical Situation 8 - Session: Practice 3', 'Klopp (Borussia Dortmund)', 'Building up under pressure and playing through the centre with a lay-off.', '2/3 of a pitch; 6v4(+1) in a 45x25 yard first zone; 3 midfielders in a 35x3 yard blue zone split in 3; striker in front of mannequins; GK; 2 mini goals.', 'GK/coach starts; yellows play into the striker, who lays off to one of the 3 midfielders depending on which section the pass came through; the other 3 run to receive behind and score. Reds score in mini goals if they win it in the first zone.', 'Only one red DM may enter the first zone.', NULL, NULL, '6v4(+1) + 4 attackers + GK', 16, 16, '2/3 of full pitch', NULL, NULL, NULL, true, true, true, NULL, 350),
  ('Lay-off combination 11v11 zonal SSG', 'conditioned_game', 'opposed', 'in_possession', 155, 155, 'Attacking Tactical Situation 8 - Session: Practice 4', 'Klopp (Borussia Dortmund)', 'Lay-off combinations through the centre in an 11v11 game.', 'As previous practice with a second full-size goal and 4 red defenders replacing the mannequins.', 'Yellows build and play through the striker''s lay-off as before. Red midfielders/forwards can track back into the blue zone; red defenders can press in the blue zone but not defend beyond the red line. Reds counter freely and must score within 8-10 seconds.', 'Defenders not beyond the red line; 8-10 second counter.', NULL, NULL, '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 360),
  ('Third man run combination through mannequins', 'combination', 'unopposed', 'in_possession', 160, 160, 'Attacking Tactical Situation 9: Practice 1', 'Klopp (Borussia Dortmund)', 'Rehearse a third man run combination to break through tight spaces between defenders.', '30 x 30 yard area with mannequins in the middle, a mini goal at each end, cone gates (red trigger gate, blue pass gate) and two groups working at the same time from opposite corners.', 'The starter dribbles through the gates; on the red gate the advanced player drops in front of the mannequins while the deeper player starts his forward run. After the blue gate the ball goes to the dropping player, who lays it first time between the mannequins into the runner''s path for a shot/pass into the mini goal.', 'Dropping player plays first time; everyone rotates one position on.', NULL, 'Pass weight and accuracy timed to the runs; runs synchronised to the trigger gate.', '2 groups of 3+ players', 6, NULL, '30 x 30 yards', 27.4, 27.4, NULL, true, false, true, NULL, 370),
  ('Third man run end to end possession', 'positional_game', 'overload', 'in_possession', 161, 161, 'Attacking Tactical Situation 9: Practice 2', 'Klopp (Borussia Dortmund)', 'Use the striker dropping and a third man run to move the ball from one end zone to the other.', '30 x 65 yard area: two end zones and a 30 x 20 central blue zone split into high and low halves. A neutral No.9 sits in the high half and two neutral midfielders in the low half; a neutral in each end zone plus outside support players.', 'Yellows play 3 (+1 neutral, +2 outside) v 3 in the first end zone, make 3 passes, then find the No.9 who drops into the low half while the neutral midfielders push forward. No.9 plays first time into the high half for a midfielder, who passes on to a team-mate in the far zone; reds do the same if they win it.', 'The third man must receive inside the high blue zone; outside players one touch when supporting, free after the combination.', NULL, NULL, '6 (+5 neutrals) v 6', 17, 17, '30 x 65 yards', 59.4, 27.4, NULL, false, false, true, NULL, 380),
  ('Build up under pressure, third man run finish', 'phase_of_play', 'overload', 'in_possession', 162, 162, 'Attacking Tactical Situation 9: Practice 3', 'Klopp (Borussia Dortmund)', 'Build up against pressure, find the dropping striker and release a midfielder''s run beyond the defence to score.', 'Two thirds of a pitch with a goal and keeper; first zone 30 x 25 yards (4 (+3) v 2 (+1)), second zone 30 x 15 yards with 3 attacking midfielders, mannequins as the back line, two mini goals behind the first zone for the reds.', 'Yellows pass forward to the No.9, who drops back; the three midfielders time their runs to receive his lay-off beyond the mannequins and shoot straight away. If the reds win the ball they attack the two mini goals.', 'Only one of the two red defensive midfielders may enter the first zone; outside players one touch; midfielders time runs for when the ball reaches the striker.', NULL, 'Accurate passing and synchronised movement; quick, accurate finishing.', '4 (+3) v 2 (+1) plus 3 attacking midfielders and GK', NULL, NULL, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 390),
  ('Third man run 11v11 zonal game', 'conditioned_game', 'opposed', 'in_possession', 163, 163, 'Attacking Tactical Situation 9: Practice 4', 'Klopp (Borussia Dortmund)', 'Apply the drop-and-third-man-run combination in a full team game with a counter for the defenders.', 'Two full goals; a 45 x 25 yard low zone (6 v 4 (+1)), a 35 x 3 yard white zone for the dropping No.9, a 35 x 15 light blue zone for 3 attacking midfielders, and a red line the defenders cannot drop past.', 'Yellows find the No.9 dropping into the white zone; the midfielders time their runs to get a pass beyond the red line as the ball reaches his feet, then finish. Reds that win the ball counter with no zone limits and must finish within 8-10 seconds.', 'One red defensive midfielder may enter the first zone; after the forward pass reds may track back; red defenders cannot defend beyond the red line or challenge the No.9 in the white zone.', NULL, NULL, '11 v 11', 22, 22, 'full pitch, zones as given', NULL, NULL, NULL, true, true, true, NULL, 400),
  ('Striker heads long pass to running midfielder', 'combination', 'unopposed', 'in_possession', 171, 172, 'Attacking Tactical Situation 10: Practice 1', 'Klopp (Borussia Dortmund)', 'Accurate long passing and heading, with the striker and a midfielder synchronised.', '30 x 40 yard area with two 25 x 10 yard blue zones and four 10 x 10 red zones, a mini goal at each end; runs on both sides at once.', 'A passes to B (after B checks to a cone), B sets C who runs on and plays a long ball into a red zone; the striker drops into it and heads forward into the path of a midfielder running into the blue zone, who finishes in the mini goal. Same pattern on the other side.', 'Players rotate one position on.', 'Practice 2 (variation): bigger gap between striker and midfielder; the long ball goes into the blue zone, the striker comes back and heads it into a red zone or down for the runner to dribble on and score.', NULL, '10 players (5 each side)', 10, NULL, '30 x 40 yards', 36.6, 27.4, NULL, true, false, true, NULL, 410),
  ('Long ball and second ball 5-zone game', 'small_sided_game', 'overload', 'in_possession', 173, 174, 'Attacking Tactical Situation 10: Practice 3', 'Klopp (Borussia Dortmund)', 'Create time to play an accurate long ball to the striker, win the knock-down or second ball and attack quickly.', '30 x 70 yard pitch in 7 strips: two 30 x 20 blue zones each split high/low, a 30 x 10 central zone and two end zones; goals with keepers at both ends, coaches with spare balls behind them.', 'From the keeper, yellows play 3 (+1 neutral, +2 outside) v 3 in the low blue zone to free a long ball to the No.9 in the high blue zone; a neutral midfielder runs on to his header and shoots while two outside midfielders join to win any clearance. If the second ball is won they must score within 8 seconds; reds who win it restart the same pattern the other way.', 'Neutral must receive the header in the high blue zone; only one defender in the high zone when the long ball is played; no limits after the header/clearance; keepers stay out of the blue zones.', NULL, 'Make space for an accurate long ball; accurate header into a small area; well-timed run by the neutral; support runners anticipate clearances and exploit the 4v3 quickly.', '7 (+2) v 7', 16, 16, '30 x 70 yards', 64.0, 27.4, NULL, true, true, true, NULL, 420),
  ('Long pass to striker 4-zone 11v11', 'conditioned_game', 'opposed', 'in_possession', 175, 175, 'Attacking Tactical Situation 10: Practice 4', 'Klopp (Borussia Dortmund)', 'Play long to the centre forward, use his header and swarm the ball area for the second ball.', 'Two thirds of a pitch marked into 4 zones (low blue build-up zone, white target zone in front of goal), full goals and keepers.', 'Yellows play long from the low zone to the striker, then attack his header in the white zone; on a clearance the team moves to the ball area to win it back. A won second ball must lead to a finish within 8 seconds; reds who win it have 10 seconds to score.', 'Red defenders cannot be in the white zone when the long ball is struck (free after header/clearance); opposition keeper cannot enter the white zone.', NULL, NULL, '11 v 11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 430),
  ('Diagonal long pass on blind side', 'combination', 'unopposed', 'in_possession', 179, 179, 'Attacking Tactical Situation 11: Practice 1', 'Klopp (Borussia Dortmund)', 'Synchronise the striker''s blind-side run with the timing of the long diagonal pass.', '30 x 40 yard area, two mini goals at one end, a 10 x 10 blue target zone on each side with a mannequin in front; mirrored on left and right.', 'A passes to B after B checks to a cone, B sets C who runs on and plays a diagonal long pass into the far blue zone; D bends his run round the blind side of the mannequin, receives on the move and shoots.', 'D has 2 touches; rotate one position on.', NULL, 'Long pass accuracy into a small zone (enlarge for age/level); timing of the pass and run; quality first touch and quick finish.', '8+ players, 2 groups', 8, NULL, '30 x 40 yards', 36.6, 27.4, NULL, true, false, true, NULL, 440),
  ('Build up under pressure plus diagonal ball', 'phase_of_play', 'overload', 'in_possession', 180, 180, 'Attacking Tactical Situation 11: Practice 2', 'Klopp (Borussia Dortmund)', 'Escape pressure in build-up and hit a diagonal ball in behind for the weak-side forward.', '25 x 15 yard white zone split into four, two 10 x 10 blue zones near goal with mannequins in front, two forwards, goal and keeper; keeper or coach starts.', 'Yellows play 4 (+3) v 2 in the white zone; once a player in the high half has time he plays a diagonal ball to the weak-side blue zone, where the forward times his run, receives and shoots. Red defenders swap every 2 minutes.', 'Long ball from the high half to the weak side; one red in each half of the white zone; the 3 outside players have 2 touches.', 'Remove one forward so the players must read where he is and switch to that weak side.', NULL, '4 (+3) v 2 plus 2 forwards and GK', NULL, NULL, '25 x 15 yards (white zone)', 22.9, 13.7, NULL, true, true, true, NULL, 450),
  ('Diagonal ball in behind with live defenders', 'phase_of_play', 'overload', 'in_possession', 181, 182, 'Attacking Tactical Situation 11: Practice 3', 'Klopp (Borussia Dortmund)', 'Play a diagonal long pass behind a live defender''s blind side for the weak-side forward to finish.', '35 x 20 yard dark blue zone split into four; forwards and red defenders in white zones ahead, each with a 10 x 10 light blue target zone; goal and keeper; two mini goals behind the build-up zone.', 'From the keeper, yellows play 4 (+3) v 2 (+1) and look for the long diagonal to the weak-side forward, who times his run into the light blue zone and scores. Reds who win it attack the mini goals.', 'Diagonal from the high half to the weak side; only one red midfielder can enter the low half; outside players 2 touches or pass within 3 seconds; red defenders stay in their white zones.', 'Practice 4: swap the two mini goals for a full goal and keeper so the reds counter at a real goal (9 v 7 dynamic game).', NULL, '9 v 7', 16, 18, '35 x 20 yards (build-up zone)', 32.0, 18.3, NULL, true, true, true, NULL, 460),
  ('Switch to full back, unopposed patterns', 'combination', 'unopposed', 'in_possession', 189, 191, 'Attacking Tactical Situation 12: Practice 1', 'Klopp (Borussia Dortmund)', 'Rehearse the combinations after switching play to the weak-side full back.', 'Half a pitch with goal and keeper, mannequins as a back four, cone gates and cones in the centre; groups start from both sides, worked right then left.', 'A dribbles through a gate, B drops to offer, they play a 1-2 and A hits a long switch to the weak-side full back who receives on the move. Then one of four patterns: winger runs behind the mannequin and crosses; winger gets the ball with three options; full back plays into space, crosses to 10/11, or beats his man and crosses.', 'No.10 starts on the strong-side cone; centre backs and holding midfielders fill the A and B roles and rotate; a second group of 4 starts the other way as soon as the first finishes.', 'Practice 2 (variation): the switch goes to the weak-side winger instead, who drives on with options to the full back overlapping, the No.9''s diagonal run or the No.10 into the box.', NULL, '8+ players plus GK', 9, NULL, 'half a full pitch', NULL, NULL, NULL, true, true, true, NULL, 470),
  ('Switch to full back v 2 centre backs', 'phase_of_play', 'opposed', 'in_possession', 192, 193, 'Attacking Tactical Situation 12: Practice 3', 'Klopp (Borussia Dortmund)', 'Read how two live centre backs react after the switch and pick the right attacking option.', 'As Practice 1 on half a pitch, but two red centre backs replace the central mannequins (full-back mannequins stay).', 'After the 1-2 and long switch, yellows react to what the centre backs do: if No.4 does not close the winger, the winger is free to finish; if he does, others exploit the gap. Worked on both sides.', NULL, 'Practice 4 (variation): two red full backs are live and the centre backs become mannequins; if the full back steps to the winger the flank opens, if he holds his zone the yellows find another solution.', 'Read the defenders'' decisions and react correctly; quick, accurate finishing.', '7 v 2 (+2 mannequins) plus GK', 10, NULL, 'half a full pitch', NULL, NULL, NULL, true, true, true, NULL, 480),
  ('Switch of play 7v4 v full back line', 'phase_of_play', 'opposed', 'in_possession', 194, 194, 'Attacking Tactical Situation 12: Practice 5', 'Klopp (Borussia Dortmund)', 'Switch play to either the weak-side full back or winger and beat a live back four.', 'Half a pitch with goal and keeper; four live red defenders, no mannequins; same starting gates and cones as before.', 'After the build-up 1-2, the switch can go to the full back or the winger; yellows then respond to the defenders'' reactions, e.g. a centre back steps to the winger, the No.9 attacks that space and a 2v1 at the far post is crossed into.', NULL, NULL, NULL, '7 v 4 plus GK', 12, NULL, 'half a full pitch', NULL, NULL, NULL, true, true, true, NULL, 490),
  ('Switch to full back 4-zone 11v10', 'conditioned_game', 'opposed', 'in_possession', 195, 195, 'Attacking Tactical Situation 12: Practice 6', 'Klopp (Borussia Dortmund)', 'Build up, switch play to the weak-side full back and finish with the right combination; reds counter if they win it.', 'Two thirds of a pitch: 30-yard low zone split left/right, 10-yard central zone for the yellow attacking midfielders, 30-yard high zone with 4 red defenders and the yellow No.9; goals at both ends.', 'From the keeper, yellows play 6 (+3) v 5 in the low zone and switch to the weak-side full back in the central zone; red defenders can enter the central zone and low-zone reds follow only once he receives. Reds that win it must score within 10 seconds.', 'The 3 attacking midfielders are one-touch outside players in the low zone; no zone limits once reds win it; restarts with the yellow keeper.', 'Switch to the weak-side winger instead of the full back.', NULL, '11 v 10', 21, 21, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 500),
  ('Switch to full back 6-zone 11v11', 'conditioned_game', 'opposed', 'in_possession', 196, 196, 'Attacking Tactical Situation 12: Practice 7', 'Klopp (Borussia Dortmund)', 'Same switching game against a full 11 with a holding midfielder ready to support after the switch.', 'As Practice 6, plus an extra central box where one of the two red defensive midfielders waits; 11 v 11.', 'Yellows play 6 (+3) v 5 in the low zone and switch to the weak-side full back; the red holding midfielder in the extra area can help straight away, other reds enter once the full back receives. Reds that win it must score within 10 seconds.', 'Same as Practice 6; only one red defensive midfielder inside the extra area.', NULL, NULL, '11 v 11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 510),
  ('Colour-call shape then direct counter, 9 strong side', 'transition', 'unopposed', 'to_attack', 215, 216, 'Positive Transition Situation 1: Practice 1', 'Klopp (Borussia Dortmund)', 'Win-the-ball-and-go: react to a turnover and counter fast with the No.9 or No.10 as the strong-side forward.', 'Two thirds of a pitch with 4 different-coloured mannequins (or big cones) as opponents, 10 small cones for start spots and 3 blue zones to attack; keeper in goal. No.9 and No.10 start on opposite sides.', 'Coach shouts colours and the team shifts into defensive shape as if that mannequin had the ball. Coach then feeds a strong-side player (winger, full back, holding mid or No.10) as if possession was won, and everyone breaks forward into the free spaces to finish.', 'Goal must be scored within 6 seconds; all players, defenders included, join the forward movement.', 'Coach feeds the ball when the No.10 is the presser on the strong side, so he acts as the strong-side forward. Two players per cone for quick restarts; No.9 swaps sides each go.', 'Quick reactions to the colour call; play it like a match using free space; accurate passing and quick finishing.', '11 attackers + GK', 11, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 520),
  ('Colour-call press and counter on flank 8v4', 'transition', 'opposed', 'to_attack', 217, 217, 'Positive Transition Situation 1: Practice 2', 'Klopp (Borussia Dortmund)', 'Collective defensive shift then a quick counter on the flank against recovering defenders.', 'As Practice 1 but 4 red defenders stand on the coloured cones; centre forward is the first presser on the strong side and receives the first pass in the blue zone behind the back line.', 'Coach calls colours, yellows shift; coach then feeds a yellow who starts the counter. Yellows attack the 4 reds who track back to defend the goal.', 'Attack must finish within 8-10 seconds.', 'No.10 becomes first presser on the strong side and first receiver in the blue zone.', NULL, '8v4 + GK', 13, 13, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 530),
  ('High press and counter, 8v8 transition game', 'transition', 'opposed', 'to_attack', 218, 218, 'Positive Transition Situation 1: Practice 3', 'Klopp (Borussia Dortmund)', 'Win the ball high and counter quickly through or beyond a red end line.', '55 x 45 yard area with a red end line and 2 mini goals for reds; a 15 x 45 yard start zone where the coach feeds the red centre backs.', 'Reds try to score in the 2 mini goals; yellows press, win it and counter by dribbling over the red end line or receiving a pass beyond it (offside applies).', 'Yellow counter must score within 6-10 seconds; reds cannot defend beyond the red end line.', NULL, 'Act as in a real game using free spaces; accurate passing and quick finishing.', '8v8', 16, 16, '55 x 45 yards', 50.3, 41.1, NULL, true, false, true, NULL, 540),
  ('Win high and counter, 3 zone 9v9 (+GK)', 'transition', 'opposed', 'to_attack', 219, 219, 'Positive Transition Situation 1: Practice 4', 'Klopp (Borussia Dortmund)', 'Press the build-up, win the ball high and finish a fast counter on a full goal.', 'Two thirds of a pitch split into 3 zones; full goal with keeper at one end, 3 mini goals at the other. Red centre backs start in the dark blue zone and receive from the keeper.', 'Reds try to get the ball to their 3 forwards in the light blue zone (holding it there 4+ seconds scores) or score in a mini goal. Yellows defend, win it and counter on the big goal.', 'Yellows must finish within 8-10 seconds; reds may not play long aerial passes.', NULL, NULL, '9v9 + GK', 19, 19, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 550),
  ('Win high and counter, 3 zone 11v11', 'conditioned_game', 'opposed', 'to_attack', 220, 220, 'Positive Transition Situation 1: Practice 5', 'Klopp (Borussia Dortmund)', 'Full-team version of the high-press and fast counter game.', 'As Practice 4 with 11v11 and a second full-size goal with keeper replacing the mini goals.', 'Reds score by holding the ball 4+ seconds with their 3 forwards in the light blue zone or by shooting; yellows win it and counter.', 'Counters must score within 8-10 seconds of winning the ball; reds may not play long aerial passes.', NULL, NULL, '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 560),
  ('Move into passing lanes, indirect counter', 'transition', 'unopposed', 'to_attack', 225, 226, 'Positive Transition Situation 2: Practice 1', 'Klopp (Borussia Dortmund)', 'After winning the ball under pressure, forwards show in passing lanes for a forward pass and lay-off before the counter.', 'Half a pitch, players on yellow cones (No.9 and No.10 on opposite sides); rows of 3 big cones block forward passing lanes; 4 coloured mannequins; blue zones mark free space; keeper in goal.', 'Coach calls colours and the team takes up defensive shape. Coach chips or throws the ball to a strong-side player; the advanced forward shows in a gap for a forward pass and sets it back to a supporting runner, then the team counters.', 'Score within 6-10 seconds.', 'Run with either the centre forward (diagram 1) or the No.10 (diagram 2) on the strong side.', 'Quick reactions after winning it; good movement into open lanes between the cones; use the blue-zone spaces; weighted passes into the runner''s path, timed runs, quick finishing.', '11 attackers + GK', 11, 12, 'Half a pitch', NULL, NULL, NULL, true, true, true, NULL, 570),
  ('Passing-lane counter 6v6 (+GK)', 'transition', 'opposed', 'to_attack', 227, 227, 'Positive Transition Situation 2: Practice 2', 'Klopp (Borussia Dortmund)', 'Indirect transition: forward pass to a showing forward, set back, then counter against live pressure.', 'As Practice 1 but 4 red defenders on coloured cones and 2 red midfielders on red cones in the centre.', 'Coach calls colours, yellows shift; coach chips or throws the ball in, giving reds time to press it. Forwards move into open lanes for a forward pass and the yellows counter.', 'Score within 6-10 seconds; either the No.9 or No.10 is on the strong side.', NULL, NULL, '6v6 + GK', 13, 13, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 580),
  ('Forward pass counter, 3 zone 8v8 game', 'transition', 'opposed', 'to_attack', 228, 228, 'Positive Transition Situation 2: Practice 3', 'Klopp (Borussia Dortmund)', 'Win the ball and counter using a forward pass and set-back combination.', '55 x 45 yard area; 10 x 45 yard start zone where the coach feeds the red centre backs, a 20 x 45 yard blue zone, red end line and 2 mini goals for reds.', 'Reds aim for the mini goals; yellows win it and counter by dribbling over the red end line or receiving beyond it (offside applies).', 'Counter within 6-10 seconds; goal counts double after a forward pass + back pass (or third man run) combination in the blue zone; reds may not play long aerial passes.', NULL, NULL, '8v8', 16, 16, '55 x 45 yards', 50.3, 41.1, NULL, true, false, true, NULL, 590),
  ('Forward pass counter, 9v9 (+GK) game', 'transition', 'opposed', 'to_attack', 229, 229, 'Positive Transition Situation 2: Practice 4', 'Klopp (Borussia Dortmund)', 'Indirect counter-attack with a combination after winning the ball in midfield.', 'Two thirds of a pitch; full goal with keeper at one end, 3 mini goals at the other.', 'Reds score by holding the ball 4+ seconds with their 3 forwards in the light blue zone or in a mini goal; yellows defend, win it and counter on the big goal.', 'Finish within 8-10 seconds; goal counts double after a forward pass and back pass or pass to a forward runner in the central zone; reds no long aerial passes.', NULL, NULL, '9v9 + GK', 19, 19, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 600),
  ('Forward pass counter, 11v11 game', 'conditioned_game', 'opposed', 'to_attack', 230, 230, 'Positive Transition Situation 2: Practice 5', 'Klopp (Borussia Dortmund)', 'Full-team indirect transition game with two big goals.', 'As Practice 4 but 11v11 with full goals and keepers at both ends.', 'Reds score with a shot or by keeping it 4+ seconds with their 4 forwards in the light blue zone; yellows win it and counter.', 'Counter within 8-10 seconds; double goal after a forward pass then back pass or pass to a forward runner in the dark blue zone; reds no long aerial passes.', NULL, NULL, '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 610),
  ('Colour-call shape, counter via switch to far full back', 'transition', 'unopposed', 'to_attack', 234, 234, 'Positive Transition Situation 3: Practice 1', 'Klopp (Borussia Dortmund)', 'When the forward pass is blocked, switch play to the weak-side full back to start the counter.', 'Two thirds of a pitch with 4 deep mannequins, 2 blue target zones near the touchlines and 4 big coloured cones; players on red cones, No.9 and No.10 on opposite sides; keeper in goal.', 'Coach calls colours, team shifts; coach feeds a strong-side player who must get the ball (directly or via a link) to the far full back in the blue zone, who has two options for a final ball in behind while all players run forward.', 'Attack lasts no more than 8-10 seconds.', 'Coach feeds when the No.10 is the first presser so he plays as the strong-side forward; two players per cone, No.9 swaps sides each go.', NULL, '11 attackers + GK', 11, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 620),
  ('Switch-of-play counter to full back 8v4', 'transition', 'opposed', 'to_attack', 235, 235, 'Positive Transition Situation 3: Practice 2', 'Klopp (Borussia Dortmund)', 'Collective defensive shift and a quick counter by switching to the full back against defenders.', 'As Practice 1 but 4 red defenders on large coloured cones replace the mannequins.', 'After the colour call the coach feeds the strong side; the ball goes to a blue target zone, the full back runs on to it and yellows try to score against the 4 reds, who can only defend inside the red zone.', 'Score within 8-10 seconds.', NULL, 'Quick reactions; full back times his run; passes in front of runners; quick 1-touch combinations; quick, accurate finishing.', '8v4 + GK', 13, 13, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 630),
  ('Switch-of-play transition game 8v8', 'transition', 'opposed', 'to_attack', 236, 236, 'Positive Transition Situation 3: Practice 3', 'Klopp (Borussia Dortmund)', 'Win possession and switch to the weak-side full back running into a side zone.', '55 x 45 yard area with a 20 x 45 yard blue zone and 2 yellow zones along the sidelines; red end line; 2 mini goals for reds.', 'Keeper or coach starts; reds try to score in the mini goals without long passes. Yellows win it, find the weak-side full back running into the yellow zone, then combine to score by dribbling over or receiving beyond the red end line.', 'Yellows score within 8-10 seconds; red defenders only defend in the low blue zone; reds cannot contest inside the yellow zones.', NULL, NULL, '8v8', 16, 16, '55 x 45 yards', 50.3, 41.1, NULL, true, false, true, NULL, 640),
  ('Switch-of-play transition game 9v9 (+GK)', 'transition', 'opposed', 'to_attack', 237, 237, 'Positive Transition Situation 3: Practice 4', 'Klopp (Borussia Dortmund)', 'Counter via a switch to the weak side after winning the ball against a building team.', 'Two thirds of a pitch, full goal with keeper vs 3 mini goals, 2 yellow side zones, high dark blue and low light blue zones.', 'Reds score by keeping the ball 4+ seconds with their 3 forwards in the low light blue zone or in a mini goal; yellows win it, switch to the weak-side yellow zone and finish on the big goal.', 'Reds no long passes; red defenders only in the high dark blue zone; reds cannot contest in the yellow zones; yellows finish within 8-10 seconds.', NULL, NULL, '9v9 + GK', 19, 19, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 650),
  ('Switch-of-play 6 zone 11v11 game', 'conditioned_game', 'opposed', 'to_attack', 238, 238, 'Positive Transition Situation 3: Practice 5', 'Klopp (Borussia Dortmund)', 'Full-team counter that goes to the weak-side target zone then combines to finish.', 'As Practice 4 with 11v11 and full goals plus keepers at both ends.', 'One side scores with a shot or by keeping it 4 seconds in the low light blue zone; on winning the ball the other side must first find the weak side''s target zone, then combine to score within 8-10 seconds.', 'Same restrictions as Practice 4.', 'Book notes all Situation 3 practices can be re-run with No.9 and No.10 both starting centrally so both can attack the strong side.', NULL, '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 660),
  ('Colour-call counter, 9 and 10 overload flank', 'transition', 'unopposed', 'to_attack', 244, 244, 'Positive Transition Situation 4: Practice 1', 'Klopp (Borussia Dortmund)', 'Direct transition with both No.9 and No.10 going to the strong side to make a 2v1 on the flank.', 'Two thirds of a pitch, No.9 and No.10 on red cones in the centre; coloured mannequins plus one extra mannequin in each blue zone near the sidelines; keeper in goal.', 'Coach calls a colour and the team shifts to defend; coach then feeds a strong-side player and yellows counter. One of No.9 / No.10 receives in the blue zone, the other runs in behind for the 2v1, then crosses or cuts back to the edge of the box.', 'Score within 6 seconds.', NULL, 'Quick reactions first, then use the free spaces.', '11 attackers + GK', 11, 12, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 670),
  ('Flank 2v1 counter, 8v6 (+GK)', 'transition', 'opposed', 'to_attack', 245, 245, 'Positive Transition Situation 4: Practice 2', 'Klopp (Borussia Dortmund)', 'Counter with No.9 and No.10 creating a 2v1 on the flank against live defenders.', 'As Practice 1 but 6 reds replace the mannequins: 4 defenders on coloured cones and midfielders 6 and 8 on yellow cones; red end line.', 'Colour call, yellows shift; coach feeds the strong side and yellows counter. A ball into No.9 or No.10 in the side blue zone should create a 2v1; they dribble over or receive beyond the red line (offside applies) before the final pass.', 'Finish within 8-10 seconds; strong-side red centre back cannot defend past the red end line; red full back may enter the blue zone only after both yellows are in it.', NULL, NULL, '8v6 + GK', 15, 15, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 680),
  ('Flank 2v1 dynamic zone transition game', 'transition', 'opposed', 'to_attack', 246, 246, 'Positive Transition Situation 4: Practice 3', 'Klopp (Borussia Dortmund)', 'Win the ball, move it to a side zone and exploit a 2v1 against the centre back.', '55 x 45 yard area: 2 yellow zones (red centre backs start in them) and 2 low blue zones with 3v3 each; yellow No.9 and No.10 on blue cones centrally; 2 mini goals for reds.', 'Coach feeds a red centre back; reds pass while No.9 and No.10 shift with the ball. When the ball goes into a blue zone by the sideline, No.10 joins to make 4v3. Reds attack the mini goals; yellows win it, play into the yellow zone and use the 2v1 to dribble over or receive beyond the red end line.', 'Strong-side red centre back cannot defend past the red end line; offside applies.', NULL, NULL, '8v8', 16, 16, '55 x 45 yards', 50.3, 41.1, NULL, true, false, true, NULL, 690),
  ('Flank 2v1 6 zone game 9v9 (+GK)', 'transition', 'opposed', 'to_attack', 247, 247, 'Positive Transition Situation 4: Practice 4', 'Klopp (Borussia Dortmund)', 'Counter that builds a flank 2v1 after pressing the build-up with both forwards on the strong side.', 'Two thirds of a pitch, full goal with keeper vs 3 mini goals; 6 zones incl. yellow side zones and a dark blue central zone; No.9 and No.10 on blue cones.', 'Keeper plays to a red centre back and both No.9 and No.10 can shift to the strong side. Reds score by keeping it 4+ seconds in the low blue zone or in a mini goal; yellows win it, move into a yellow zone and use the 2v1 before scoring.', 'Yellows finish within 8-10 seconds; red centre backs receive outside the dark blue zone; attack on the side the keeper''s first pass went, no long balls; strong-side red CB not past the red end line; red full back enters the yellow zone only after both yellows have.', NULL, NULL, '9v9 + GK', 19, 19, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 700),
  ('Flank 2v1 6 zone game 11v11', 'conditioned_game', 'opposed', 'to_attack', 248, 248, 'Positive Transition Situation 4: Practice 5', 'Klopp (Borussia Dortmund)', 'Full-team version: create and use the 2v1 in the side zones on the counter.', 'As Practice 4 with 11v11 and full goals plus keepers at both ends.', 'Same aims as Practice 4 but both teams shoot at keepers.', 'Same restrictions as Practice 4.', NULL, 'Be tactically aware to create and exploit the 2v1 in the side yellow zones.', '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 710)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'jurgen-klopp-s-attacking-tactics-tactical-analysis-and-sessions-from-borussia-do') b;
